 14	contract S6PurchaseHandler is IERC721Receiver {
 15	    MockQuoteToken public immutable quote;
 16	    Raffle public immutable raffle;
 17	    uint256 public calls;
 18	
 19	    constructor(MockQuoteToken quote_, Raffle raffle_) {
 20	        quote = quote_;
 21	        raffle = raffle_;
 22	        quote_.approve(address(raffle_), type(uint256).max);
 23	    }
 24	
 25	    function buy(uint128 rawEntries) external {
 26	        uint128 entries = uint128(uint256(rawEntries) % 1_000 + 1);
 27	        raffle.buyEntries(address(this), entries);
 28	        ++calls;
 29	    }
 30	
 31	    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
 32	        return IERC721Receiver.onERC721Received.selector;
 33	    }
 34	}
