 36	contract S6InvariantTest is S6TestBase {
 37	    uint256 internal constant ENTRY_PRICE = 1_000_000;
 38	    address internal constant SPONSOR_RECIPIENT = address(0x6200);
 39	    address internal constant TREASURY = address(0x6300);
 40	
 41	    MockQuoteToken internal quote;
 42	    MockVrfWrapper internal wrapper;
 43	    RaffleFactory internal factory;
 44	    HonestPrize internal prize;
 45	    Raffle internal raffle;
 46	    S6PurchaseHandler internal handler;
 47	    address[] private _targetedContracts;
 48	
 49	    function setUp() public {
 50	        quote = new MockQuoteToken();
 51	        wrapper = new MockVrfWrapper(address(quote));
 52	        factory = new RaffleFactory(address(quote), address(wrapper), TREASURY);
 53	        prize = new HonestPrize();
 54	        prize.mint(address(this), 1);
 55	        prize.approve(address(factory), 1);
 56	        raffle = Raffle(
 57	            payable(
 58	                factory.createRaffle(
 59	                    IRaffleFactory.CreateRaffleParams({
 60	                        sponsorRecipient: SPONSOR_RECIPIENT,
 61	                        prizeToken: address(prize),
 62	                        prizeTokenId: 1,
 63	                        reserveEntries: type(uint128).max,
 64	                        endTime: uint64(block.timestamp + 30 days)
 65	                    })
 66	                )
 67	            )
 68	        );
 69	        handler = new S6PurchaseHandler(quote, raffle);
 70	        quote.mint(address(handler), uint256(type(uint128).max) * ENTRY_PRICE);
 71	        _targetedContracts.push(address(handler));
 72	    }
 73	
 74	    function targetContracts() external view returns (address[] memory) {
 75	        return _targetedContracts;
 76	    }
 77	
 78	    function invariant_RangesRemainAContiguousPartition() public view {
 79	        uint256 tickets = raffle.ticketCount();
 80	        uint256 expectedFirst = 1;
 81	        for (uint256 ticketId = 1; ticketId <= tickets; ++ticketId) {
 82	            (uint128 firstEntry, uint128 lastEntry) = raffle.ticketRange(ticketId);
 83	            assertEq(firstEntry, expectedFirst, "range begins after predecessor");
 84	            assertTrue(lastEntry >= firstEntry, "range nonempty");
 85	            assertEq(raffle.ownerOf(ticketId), address(handler), "handler owns live ticket");
 86	            expectedFirst = uint256(lastEntry) + 1;
 87	        }
 88	        assertEq(expectedFirst - 1, raffle.totalEntries(), "partition ends at totalEntries");
 89	        assertEq(tickets, handler.calls(), "one ticket per successful action");
 90	    }
 91	
 92	    function invariant_ActiveSalesAccountingMatchesCustodyAndGross() public view {
 93	        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Active), "sales remain active");
 94	        assertEq(raffle.unsettledPot(), raffle.grossSales(), "unsettled equals lifetime sales");
 95	        assertEq(raffle.accountedQuoteBalance(), raffle.grossSales(), "liability equals lifetime sales");
 96	        assertEq(quote.balanceOf(address(raffle)), raffle.accountedQuoteBalance(), "custody covers liability");
 97	        assertTrue(raffle.ticketCount() <= raffle.totalEntries(), "each ticket represents at least one entry");
 98	    }
 99	
100	    function invariant_NoTerminalLiabilitiesDuringActiveSales() public view {
101	        assertEq(raffle.remainingRefundLiability(), 0, "no refunds allocated");
102	        assertEq(raffle.winnerProceeds(), 0, "no winner allocated");
103	        assertEq(raffle.sponsorProceeds(), 0, "no sponsor allocated");
104	        assertEq(raffle.protocolFees(), 0, "no protocol allocated");
105	        assertFalse(raffle.settlementComplete(), "not settled");
106	        assertFalse(raffle.winnerRedeemed(), "not redeemed");
107	        assertFalse(raffle.prizeClaimed(), "prize remains escrowed");
108	    }
109	}
