 38	                        reserveEntries: type(uint128).max,
 39	                        endTime: uint64(block.timestamp + 30 days)
 40	                    })
 41	                )
 42	            )
 43	        );
 44	        quote.mint(address(this), uint256(type(uint128).max) * ENTRY_PRICE);
 45	        quote.approve(address(raffle), type(uint256).max);
 46	    }
 47	
 48	    function buy(uint128 rawEntries) external {
 49	        if (successfulBuys >= MAX_ACTIONS) return;
 50	        uint128 entries = uint128(uint256(rawEntries) % 1_000 + 1);
 51	        raffle.buyEntries(address(this), entries);
 52	        ++successfulBuys;
 53	    }
 54	
 55	    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
 56	        return IERC721Receiver.onERC721Received.selector;
 57	    }
 58	
 59	    function echidna_active_sales_accounting_equals_custody() external view returns (bool) {
 60	        return raffle.status() == IRaffle.Status.Active && raffle.unsettledPot() == raffle.grossSales()
 61	            && raffle.accountedQuoteBalance() == raffle.grossSales()
 62	            && quote.balanceOf(address(raffle)) == raffle.accountedQuoteBalance();
 63	    }
 64	
 65	    function echidna_ranges_form_contiguous_partition() external view returns (bool) {
 66	        uint256 tickets = raffle.ticketCount();
 67	        uint256 expectedFirst = 1;
 68	        for (uint256 ticketId = 1; ticketId <= tickets; ++ticketId) {
 69	            (uint128 firstEntry, uint128 lastEntry) = raffle.ticketRange(ticketId);
 70	            if (firstEntry != expectedFirst || lastEntry < firstEntry || raffle.ownerOf(ticketId) != address(this)) {
 71	                return false;
 72	            }
 73	            expectedFirst = uint256(lastEntry) + 1;
 74	        }
 75	        return expectedFirst - 1 == raffle.totalEntries() && tickets == successfulBuys;
 76	    }
 77	
 78	    function echidna_no_terminal_liabilities_during_active_sales() external view returns (bool) {
 79	        return raffle.remainingRefundLiability() == 0 && raffle.winnerProceeds() == 0
 80	            && raffle.sponsorProceeds() == 0 && raffle.protocolFees() == 0 && !raffle.settlementComplete()
 81	            && !raffle.winnerRedeemed() && !raffle.prizeClaimed();
 82	    }
 83	
 84	    function echidna_factory_registry_is_bidirectionally_consistent() external view returns (bool) {
 85	        return factory.raffleCount() == 1 && factory.raffleById(1) == address(raffle)
 86	            && factory.idByRaffle(address(raffle)) == 1 && factory.isRaffle(address(raffle));
 87	    }
 88	}

