 20	contract MockQuoteToken is IERC20Metadata {
 21	    string public constant name = "S6 Quote";
 22	    string public constant symbol = "S6Q";
 23	    uint8 public constant decimals = 6;
 24	
 25	    uint256 public totalSupply;
 26	    uint256 public feeBps;
 27	    bool public returnFalse;
 28	    address public callbackTarget;
 29	    bytes public callbackData;
 30	    bool public callbackOnTransferFrom;
 31	    bool public callbackAttempted;
 32	    bool public callbackSucceeded;
 33	    bool private _insideCallback;
 34	
 35	    mapping(address account => uint256 amount) public balanceOf;
 36	    mapping(address owner => mapping(address spender => uint256 amount)) public allowance;
 37	
 38	    function mint(address to, uint256 amount) external {
 39	        totalSupply += amount;
 40	        balanceOf[to] += amount;
 41	        emit Transfer(address(0), to, amount);
 42	    }
 43	
 44	    function setFeeBps(uint256 newFeeBps) external {
 45	        require(newFeeBps <= 10_000, "fee");
 46	        feeBps = newFeeBps;
 47	    }
 48	
 49	    function setReturnFalse(bool enabled) external {
 50	        returnFalse = enabled;
 51	    }
 52	
 53	    function configureCallback(address target, bytes calldata data, bool enabled) external {
 54	        callbackTarget = target;
 55	        callbackData = data;
 56	        callbackOnTransferFrom = enabled;
 57	        callbackAttempted = false;
 58	        callbackSucceeded = false;
 59	    }
 60	
 61	    function approve(address spender, uint256 amount) external returns (bool) {
 62	        allowance[msg.sender][spender] = amount;
 63	        emit Approval(msg.sender, spender, amount);
 64	        return !returnFalse;
 65	    }
 66	
 67	    function transfer(address to, uint256 amount) external returns (bool) {
 68	        if (returnFalse) return false;
 69	        _move(msg.sender, to, amount);
 70	        return true;
 71	    }
 72	
 73	    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
 74	        if (returnFalse) return false;
 75	        uint256 allowed = allowance[from][msg.sender];
 76	        if (allowed != type(uint256).max) {
 77	            require(allowed >= amount, "allowance");
 78	            allowance[from][msg.sender] = allowed - amount;
 79	        }
 80	
 81	        if (callbackOnTransferFrom && !_insideCallback) {
 82	            _insideCallback = true;
 83	            callbackAttempted = true;
 84	            (callbackSucceeded,) = callbackTarget.call(callbackData);
 85	            _insideCallback = false;
 86	        }
 87	
 88	        _move(from, to, amount);
 89	        return true;
 90	    }
 91	
 92	    function _move(address from, address to, uint256 amount) private {
 93	        require(to != address(0), "zero");
 94	        uint256 fromBalance = balanceOf[from];
 95	        require(fromBalance >= amount, "balance");
 96	        balanceOf[from] = fromBalance - amount;
 97	        uint256 fee = amount * feeBps / 10_000;
 98	        uint256 received = amount - fee;
 99	        balanceOf[to] += received;
100	        if (fee != 0) totalSupply -= fee;
101	        emit Transfer(from, to, received);
102	        if (fee != 0) emit Transfer(from, address(0), fee);
103	    }
104	}
